import re

def natural_sort_strings(strings):
    def _key(s):
        runs = re.findall(r'\d+|\D+', s)
        key_parts = []
        for run in runs:
            if run.isdigit():
                key_parts.append(int(run))
            else:
                key_parts.append(run)
        return key_parts

    decorated = [(_key(s), i, s) for i, s in enumerate(strings)]
    decorated.sort(key=lambda x: (x[0], x[1]))
    return [t[2] for t in decorated]
