def natural_sort_strings(arr):
    key_map = {}
    for i, s in enumerate(arr):
        tokens = []
        pos = 0
        while pos < len(s):
            if s[pos].isdigit():
                j = pos
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(('N', int(s[pos:j])))
                pos = j
            else:
                j = pos
                while j < len(s) and not s[j].isdigit():
                    j += 1
                tokens.append(('T', s[pos:j]))
                pos = j
        key_map[i] = (tokens, len(tokens))

    def sort_key(idx):
        tokens, length = key_map[idx]
        normalized = []
        for kind, val in tokens:
            if kind == 'N':
                normalized.append((0, val))
            else:
                normalized.append((1, val))
        return (normalized, length, idx)

    indices = list(range(len(arr)))
    indices.sort(key=sort_key)
    return [arr[i] for i in indices]
