```python
def natural_sort_strings(strings):
    """Sort strings by natural order: digit runs compared as integers, non-digit runs lexicographically case-sensitive.

    Shorter equal-prefix token lists sort first. Equal keys preserve input order.
    Empty strings sort before all other strings.
    Unicode digit characters are treated as text (non-digit).
    """
    def _key(s):
        if s == "":
            return (-1,)
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            # gather a maximal run of consecutive ASCII digits
            if s[i].isdigit() and ord(s[i]) < 128:
                j = i
                while j < n and s[j].isdigit() and ord(s[j]) < 128:
                    j += 1
                tokens.append(('D', int(s[i:j])))
                i = j
            else:
                # non-digit run (including Unicode digits)
                j = i
                while j < n and not (s[j].isdigit() and ord(s[j]) < 128):
                    j += 1
                tokens.append(('T', s[i:j]))
                i = j
        return tuple(tokens)

    # Python's sort is stable, so equal keys preserve input order
    return sorted(strings, key=_key)
