import functools

def natural_sort_strings(arr):
    key_parts = []
    for s in arr:
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(('D', int(s[i:j])))
                i = j
            else:
                j = i
                while j < n and not s[j].isdigit():
                    j += 1
                tokens.append(('N', s[i:j]))
                i = j
        key_parts.append(tokens)

    @functools.cmp_to_key
    def compare(a_idx, b_idx):
        a_tokens = key_parts[a_idx]
        b_tokens = key_parts[b_idx]
        min_len = min(len(a_tokens), len(b_tokens))
        for i in range(min_len):
            a_kind, a_val = a_tokens[i]
            b_kind, b_val = b_tokens[i]
            if a_kind != b_kind:
                return -1 if a_kind == 'N' else 1
            if a_kind == 'N':
                if a_val < b_val:
                    return -1
                elif a_val > b_val:
                    return 1
            else:
                if a_val < b_val:
                    return -1
                elif a_val > b_val:
                    return 1
        if len(a_tokens) < len(b_tokens):
            return -1
        elif len(a_tokens) > len(b_tokens):
            return 1
        return 0

    indices = list(range(len(arr)))
    indices.sort(key=functools.cmp_to_key(compare))
    return [arr[i] for i in indices]

